// Resolves which local image each catalog record shows. Output: api/v1/visuals.json (generated by `npm run build`).
//
// Fallback order (first hit wins, every step is a local file):
//   1. brand   brand-mark asset whose manifest target is the exact app / vendor / tool
//   2. component / category / bundle   glyph asset targeted at the component, category or bundle
//   3. bundled vector   a fixed interface glyph in assets/icons/navigation or hardware (always present)
// Photos are used only where a record has a photo target in the manifest (bundle covers, page banners).
// The browser repeats the same chain at render time (assets/js/lib/visuals.js) in case a file fails to load.

export const VISUALS_SCHEMA = 'anto-ltg.visuals/1';

// Bundled vectors that every record can always fall back to. Each file must exist.
export const BUNDLED = {
  software: 'assets/icons/navigation/software.svg',
  tool: 'assets/icons/navigation/wrench.svg',
  driver: 'assets/icons/hardware/card.svg',
  vendor: 'assets/icons/navigation/chip.svg',
  category: 'assets/icons/navigation/folder.svg',
  bundle: 'assets/icons/navigation/bundle.svg',
};

function indexAssets(manifest) {
  // key "type:id" -> { asset, file, brand } ; the first asset wins, and the manifest order keeps this deterministic.
  const index = new Map();
  for (const asset of manifest.assets ?? []) {
    for (const t of asset.targets ?? []) {
      const file = (asset.files ?? []).find((f) => f.format === 'svg') ?? (asset.kind === 'photo' ? null : asset.files?.[0]);
      const entry = { asset, file, role: t.role ?? null };
      index.set(`${t.type}:${t.id}:${t.role ?? ''}`, entry);
      // Photos are reachable only through their role, so they never shadow a vector glyph for the same record.
      if (asset.kind !== 'photo' && !index.has(`${t.type}:${t.id}`)) index.set(`${t.type}:${t.id}`, entry);
    }
  }
  return index;
}

function vectorEntry(hit, level, bundledPath) {
  if (hit && hit.file && hit.asset.kind !== 'photo') {
    return { level, src: hit.file.path, alt: hit.asset.alt ?? '', asset: hit.asset.id };
  }
  return { level: 'bundled', src: bundledPath, alt: '', asset: null };
}

function photoEntry(asset) {
  const variants = asset.files.map((f) => ({ format: f.format, width: f.width, height: f.height, src: f.path }));
  const widths = [...new Set(variants.map((v) => v.width))].sort((a, b) => a - b);
  return { asset: asset.id, alt: asset.alt ?? '', variants, widths };
}

export function buildVisuals({ catalogs, manifest }) {
  const idx = indexAssets(manifest);
  const pick = (type, id, { brandOnly = false } = {}) => {
    const hit = idx.get(`${type}:${id}`);
    if (!hit || hit.asset.kind === 'photo') return null;
    if (brandOnly && hit.asset.kind !== 'brand-mark') return null;
    return hit;
  };
  const items = { apps: {}, tools: {}, drivers: {}, vendors: {}, bundles: {}, categories: {} };

  for (const app of catalogs.apps.items) {
    const brand = pick('app', app.id, { brandOnly: true });
    if (brand) items.apps[app.id] = vectorEntry(brand, 'brand', BUNDLED.software);
    else items.apps[app.id] = vectorEntry(pick('category', app.category), 'category', BUNDLED.software);
  }
  for (const tool of catalogs.tools.items) {
    const brand = pick('tool', tool.id, { brandOnly: true });
    if (brand) items.tools[tool.id] = vectorEntry(brand, 'brand', BUNDLED.tool);
    else items.tools[tool.id] = vectorEntry(pick('category', tool.category), 'category', BUNDLED.tool);
  }
  for (const drv of catalogs.drivers.items) {
    const vendor = drv.vendor_id ? pick('vendor', drv.vendor_id, { brandOnly: true }) : null;
    if (vendor) items.drivers[drv.id] = vectorEntry(vendor, 'brand', BUNDLED.driver);
    else items.drivers[drv.id] = vectorEntry(pick('component', drv.component), 'component', BUNDLED.driver);
  }
  for (const v of catalogs.vendors.items) {
    items.vendors[v.id] = vectorEntry(pick('vendor', v.id, { brandOnly: true }), 'brand', BUNDLED.vendor);
  }
  for (const b of catalogs.bundles.items) {
    const cover = idx.get(`bundle:${b.id}:cover`);
    items.bundles[b.id] = {
      ...vectorEntry(pick('bundle', b.id), 'glyph', BUNDLED.bundle),
      photo: cover && cover.asset.kind === 'photo' ? cover.asset.id : null,
    };
  }
  const categories = new Set(catalogs.apps.items.map((a) => a.category));
  for (const c of categories) items.categories[c] = vectorEntry(pick('category', c), 'category', BUNDLED.category);

  const photos = {};
  for (const asset of manifest.assets ?? []) {
    if (asset.kind === 'photo') photos[asset.id] = photoEntry(asset);
  }
  // Page-level image roles, e.g. pages.software.banner -> leaf-droplets
  const pages = {};
  for (const asset of manifest.assets ?? []) {
    if (asset.kind !== 'photo') continue;
    for (const t of asset.targets ?? []) {
      if (t.type !== 'page' && t.type !== 'site') continue;
      const key = t.type === 'site' ? 'site' : t.id;
      pages[key] ??= {};
      pages[key][t.role] = asset.id;
    }
  }
  return { schema: VISUALS_SCHEMA, bundled: BUNDLED, items, photos, pages };
}

export function resolveBrandCoverage(visuals) {
  const count = (group) => {
    const values = Object.values(group);
    return { total: values.length, brand: values.filter((v) => v.level === 'brand').length, bundled: values.filter((v) => v.level === 'bundled').length };
  };
  return Object.fromEntries(Object.entries(visuals.items).map(([k, v]) => [k, count(v)]));
}
